import{_ as s,O as a,o as r,c as i,a as o,i as n,f as l}from"./chunks/framework.fmIt2z2h.js";const _=JSON.parse('{"title":"D.09　爱、照护、承认、意义与生活质量","description":"","frontmatter":{"title":"D.09　爱、照护、承认、意义与生活质量","xkChars":645,"xkLessons":{"D.09":{"title":"D.09　爱、照护、承认、意义与生活质量","lead":"有人替你完成一次事务，确实可以是帮助；长期是否减负，还要看谁发现需要、安排、提醒和查验。爱与照护也不只是一张事务清单，陪伴、安静、休息和哀悼可以有自身意义。","explanation":["原文定位：第4657—4672行；原文锚点 section-d-09；短引文：‘劳动可被替代不等于所爱对象可被替代，减少事务也不必消除失落。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","本节把爱、照护与承认拆成相关但不等同的问题。爱可作为体验、关系、行动与规范理解；照护涉及识别需要、承担、实施和回应；承认涉及地位、尊重与共同生活。若将这些全部压成系统功能增益，就会遗漏体验本身、人与人关系的不可替代位置以及如何对待彼此的规范问题。","私人陪伴、安静观看、休息、希望与哀悼，不需要先证明群体结构发生可检测变化才有意义。框架的经验门槛用于限制某些特定知识断言，不应成为生活价值的总准入证。若声称某项活动修复了制度反馈，当然需相应证据；但没有该证据，不等于当事人的陪伴、安静或纪念毫无价值。","自愿、公平、能力与结果应分别取证。愿意帮助不说明负担分配已公平，付出巨大不证明能安全拒绝，成本低也不证明没有善意。能力回答能否承担，结果回答发生了什么，不能由真诚意愿替代能力或后果核查，也不能因某次未达预期就删除该行动及其可评价性。","HV11用于特定有限承担的描述与条件后果，不是爱的总定义，更不是成本越高人格越好的量表。使用时应守适用任务与具体条件，不把日常善意、陪伴和关系经验强行纳入。强制下实际承担可能产生效果，仍不能从效果倒推出自由同意；有限承担成立也不授权他人继续索取无限牺牲。","死亡、离散、关系结束与组织退场的对象和时钟不同。法律关系、实际接触、生活安排、情感联系与哀悼变化可能不同步；组织X0只属于其限定对象，不能改作人的死亡或一种人人必经的哀伤阶段。这里不提供临床哀伤分期，而是提醒记录应保留每个过程自己的问题和时间。","希望可以支持行动，但愿望、概率判断、计划与可修订承诺不是同一种语句。希望团聚不表示团聚概率很高，有愿望不表示已经安排可行计划，作出承诺还需说明自己的控制能力、条件和可修订边界。对未来诚实不必取消希望；也不能用希望给别人制造已被保证的未来。","退出关系可能需要停止直接接触，同时存在儿童或其他依赖者需要安全照护接续。接续不应迫使受害者继续暴露；退出正当也不自动回答所有具有独立依据的有限义务。实际安排要按具体安全与专业条件处理，本讲只作原则边界，不给个案法律意见。可比较独立渠道、合适接续者等概念位置，而不能未经事实与授权指派任何真人承担。","照护劳动不仅是执行：发现需要、安排日程、提醒、查验与待命也可能持续消耗注意和时间。一次事务完成可构成真实帮助；若进一步声称长期减轻某人的负担，要看协调工作是否仍集中于该人、是否新增管理协助者的工作。不能因为帮助有限就说根本没有帮助，也不能把有限帮助自动扩大为公平分担已实现。","事务可替代性与关系对象不可替代性不矛盾。新的照护者可能接手买菜或安排出行，但这不意味着原来的所爱之人可被同等替换；事务减少也不保证失落减少。关系意义、实际工作量和情绪变化是不同维度，不能由服务填补单项就宣布关系丧失已被解决。","幸福、尊严、免于伤害与意义可并列评价，不必强迫本人接受分析者决定一切的总分。若为了有限决策采用合成指标，须公开权重和不可抵销要求，不能让高幸福分数抵销未被许可的伤害或剥夺。本节重点是防止指标代替当事人生活，而非否认任何实际比较。","九个入口依次是爱作为经验关系行动，Gilligan与Tronto等照护伦理，Hegel与Honneth等承认传统，Kierkegaard、Sartre、Camus、Frankl等意义探讨，死亡哀悼记忆终结，牺牲礼物奉献消耗，希望信仰承诺未来，孤独归属友谊亲密，以及痛苦幸福欲望生活质量。目录表明问题跨度，不授权把各思想家的差异消成一套机制。最强反方担心分项会稀释真诚；回应是分清条件能保护真实关怀，同时减少以关怀之名要求无边界牺牲。"],"distinctions":[{"leftTitle":"一次帮助","leftText":"某项事务或需要确实得到承接。","rightTitle":"长期减负与公平","rightText":"还需检查协调、待命、分配和持续后果。"},{"leftTitle":"愿意付出","leftText":"表达或行动显示帮助意愿。","rightTitle":"安全拒绝与公平","rightText":"高成本不证明自由，意愿不证明分配公平。"},{"leftTitle":"事务可替代","leftText":"他人能完成某些工作。","rightTitle":"关系对象可替代","rightText":"工作接手不能据此宣称所爱的人可以替换。"},{"leftTitle":"希望与愿望","leftText":"对未来有所期待或珍视。","rightTitle":"概率计划承诺","rightText":"各有证据、能力、安排和修订条件。"},{"leftTitle":"组织退场X0","leftText":"适用对象的组织状态标记。","rightTitle":"死亡与哀悼","rightText":"对象时钟不同，不可套为通用人生阶段。"}],"boundaries":["不把HV11当全部爱或善意的定义，不按成本给人格排名。","不将组织X0套用个人死亡、丧失或哀伤阶段，不作临床诊断。","安全照护接续不能成为迫使受害者继续暴露的理由；具体义务需独立依据。","不据本文给真实关系作退出、接触或法律义务裁决。","真实来源仅限作者公开研究介绍的概念陈述，不以摘要补写访谈个案或全文统计。"],"questions":["长期减负为什么不能只数执行次数？","低成本帮助是否必然缺少善意？","希望与概率判断为何应分开？","事务有人接替为何不保证失落消失？"],"diagramPath":"/reading-assets/S-D-09/figures/section-d-09.png","caseLinks":[{"title":"作者一手研究介绍：把认知劳动纳入家务问题","href":"https://allison-daminger.squarespace.com/research"}],"caseNotes":[{"title":"作者一手研究介绍：把认知劳动纳入家务问题","text":"社会学者Allison Daminger在自己的Research页面“The Cognitive Dimension of Household Labor”首段，将预见需要、寻找可行选项、作出决定和跟进结果明确作为认知劳动。这份本人公开说明提供了一个检查协调劳动的实际研究入口；本讲据此提出核查问题，不据该页面补写任何夫妻访谈细节或推断全部家庭的分工比例。","sourceLabel":"Allison Daminger本人Research页面，当前所读版本","sourceUrl":"https://allison-daminger.squarespace.com/research","sourceLocator":"Research页“The Cognitive Dimension of Household Labor”标题后第一段（页面行11—12）；第二段及所列2019/2020论文仅用于确认项目导航","boundary":"这是作者项目介绍，不是本讲已通读的完整论文或个体访谈。未采用网页170+访谈为2019论文样本数，也不据此宣称普遍因果或某个家庭已减负。","href":"https://allison-daminger.squarespace.com/research"}],"sourceRefs":[{"section":"D.09","start_line":4657,"end_line":4672,"startLine":4657,"endLine":4672}],"outputId":"section-d-09","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["辨明谈的是体验、关系、照护工作、承认地位还是特定结构结果。","分别核自愿、公平、能力和效果，成本不能代替这些判断。","区分死亡离散关系结束组织退场的对象与时钟，保留希望与事实预测的边界。","检查执行之外的发现安排提醒查验待命，分别承认一次帮助与长期减负。","对退出后的接续同时保留安全与独立有限义务，多维评价不越过本人生活目标。"],"teachingExamples":[{"title":"教学构造：买菜帮忙是真的，协调仍未转移","text":"假想甲列出全部清单、确认库存、提醒出门并核对遗漏，乙按单完成一次买菜。乙确实承接了采购执行，不能说毫无帮助；若甲仍承担全部发现、安排与检查，则不能仅据此宣布甲的长期照护负担已公平分担。","assumptions":"人物与事务为作者教学构造，不是已发表访谈。","boundary":"未计真实工时或心理负担，不能以一次例推断长期人格或公平全貌。"},{"title":"原文教学例展开：退出与安全接续","text":"假想一段关系结束后，为保护一方安全须停止直接接触，但一位依赖者仍需要照护接续。分析应分别查安全需求、独立义务及可行接续，不能以依赖者需要要求受害者继续暴露，也不能因退出有正当理由就删除所有尚需核查的义务。","assumptions":"沿原文构造，不涉及真实儿童、家庭或司法决定。","boundary":"不确定谁依法负何义务，不指派实际接续者；现实高风险情境应由相应专业和安全程序处理。"},{"title":"教学构造：代办事务不能代替所爱之人","text":"假想失去亲密者后，朋友接手每周采购和送件，实际减轻了事务。本人仍有强烈失落并不证明朋友的帮助无效，也不表示应当因事务已解决而停止哀悼。工作负担、关系意义与情感过程分别描述。","assumptions":"完全虚构的失落与支持情境，非临床哀伤案例。","boundary":"不设哀悼期限，不推断疾病，也不要求接受某一种情感结果。"},{"title":"教学构造：未达预期仍有可评价行动","text":"假想一人自愿为邻居准备安静陪伴，但对方当天更希望独处，陪伴没有带来预期安慰。可描述帮助意图、实际安排和回应不匹配，再调整支持；不能把未成效果伪记成功，也无需说这次行动从未发生或完全不可评价。","assumptions":"人物与反应均为教学设定。","boundary":"不由意图免除倾听回应，也不由结果不理想裁定人格。"}],"counterexamples":[{"identity":"constructed_boundary","text":"他愿意做而且付出很多，所以照护分配公平且可以安全拒绝。","effect":"意愿、成本、公平与拒绝条件需分别核，不能互相替代。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"已经有人接替所有事务，所以应当不再感到失落。","effect":"事务接替不等于关系对象替代，也不控制哀悼时间。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"陪伴没有引起可检测群体结构变化，因此没有意义。","effect":"特定结构结果的证据门槛不是全部生活价值的准入证。","sourceIds":["theory"]}],"questionAnswers":[{"question":"长期减负为什么不能只数执行次数？","answer":"发现需要、安排提醒查验和待命可能仍由同一人承担，且管理帮助本身可能增加工作。","basis":"本节原文及上述公开推导"},{"question":"低成本帮助是否必然缺少善意？","answer":"不，成本不是善意或爱的通用尺度，需按实际关系行为与回应判断。","basis":"本节原文及上述公开推导"},{"question":"希望与概率判断为何应分开？","answer":"珍视未来并不提供事件可能性的证据，计划和承诺另涉及能力与安排。","basis":"本节原文及上述公开推导"},{"question":"事务有人接替为何不保证失落消失？","answer":"关系对象和工作功能不同，减少事务不等于替换所爱之人。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-09/figures/section-d-09.png","alt":"爱／照护／承认，体验关系规范，不压成单一功能；自愿／公平，能力／效果，各自核查；事务执行之外，发现安排提醒，查验与待命；一次帮助可真实，长期减负另需证据；退出后的安全接续，不强迫继续暴露，独立有限义务另核；事务可替代，不等于关系可替代，意义不必先得总分。作者依D.09绘制；人物和关系均为教学构造，不裁定真实个案义务或哀悼阶段。","caption":"作者依D.09绘制；人物和关系均为教学构造，不裁定真实个案义务或哀悼阶段。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换执行与协调是否都承接、是否能安全拒绝、是否存在独立接续义务，检查有限结论。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"限用作者本人公开界定的研究对象作为协调劳动核查入口；事实深度止于已读原页面，不冒称完整研究复核。"},"openQuestions":["未取得09.01—09.09全部原研究，不能复原各思想传统的完整论证或采纳史。","未取得本案例完整论文及原始访谈；作者介绍仅支持概念和项目存在，不支持个体案例或群体比例。"],"taskId":"S-D-09","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4657—4672行；每节精确范围见sourceRefs","claim_support":["D.09：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"daminger-project","title":"Research — The Cognitive Dimension of Household Labor","url":"https://allison-daminger.squarespace.com/research","source_type":"primary","version_or_date":"访问时页面，未标发布日期","locator":"项目同名标题后第一段（行11—12），相邻第二段及2019/2020论文链接只作导航","claim_support":["本人将预见需要、识别选项、决定和跟进列入认知劳动研究对象"],"limits":["项目介绍，不是全文或原始访谈；不据此推断个人案例、2019样本量或普遍效果。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-09/lecture.md","sourcesPath":"/reading-assets/S-D-09/sources.json","sourceSlicePath":"/reading-assets/S-D-09/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-09/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-09.md","filePath":"theory/appendix-d/d-09.md"}'),c={name:"theory/appendix-d/d-09.md"};function d(p,e,u,h,m,g){const t=a("SectionLesson");return r(),i("div",null,[e[0]||(e[0]=o("",1)),n(t,{section:"D.09"}),e[1]||(e[1]=l("div",{class:"theory-source"},null,-1))])}const x=s(c,[["render",d]]);export{_ as __pageData,x as default};
